package server

import (
	"errors"
	"flag"
	"fmt"
	"os"
	"strconv"
)

const defaultPort = 8080

// Config holds the server's runtime configuration.
type Config struct {
	DataDir string
	Port    int
}

// ParseConfig parses server configuration from CLI flags, falling back to
// SYNCBOX_DATA_DIR/SYNCBOX_PORT environment variables when the corresponding
// flag is not given.
func ParseConfig(args []string) (Config, error) {
	fs := flag.NewFlagSet("syncbox-server", flag.ContinueOnError)

	envPort := defaultPort
	if v := os.Getenv("SYNCBOX_PORT"); v != "" {
		p, err := strconv.Atoi(v)
		if err != nil {
			return Config{}, fmt.Errorf("invalid SYNCBOX_PORT %q: %w", v, err)
		}
		envPort = p
	}

	dataDir := fs.String("data-dir", os.Getenv("SYNCBOX_DATA_DIR"), "path to the data directory (required; env SYNCBOX_DATA_DIR)")
	port := fs.Int("port", envPort, "port to listen on (default 8080; env SYNCBOX_PORT)")

	if err := fs.Parse(args); err != nil {
		return Config{}, err
	}

	if *dataDir == "" {
		return Config{}, errors.New("--data-dir is required (or set SYNCBOX_DATA_DIR)")
	}

	return Config{DataDir: *dataDir, Port: *port}, nil
}

package server

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"io"
	"net/http"
	"os"
	"path/filepath"
)

// NewHandler builds the top-level HTTP handler for the syncbox server.
func NewHandler(cfg Config) http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("/healthz", handleHealthz)

	h := &blobHandler{dataDir: cfg.DataDir}
	mux.HandleFunc("PUT /blobs/{key...}", h.put)
	mux.HandleFunc("GET /blobs/{key...}", h.get)

	return mux
}

func handleHealthz(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

type blobHandler struct {
	dataDir string
}

type putResponse struct {
	Key    string `json:"key"`
	SHA256 string `json:"sha256"`
	Size   int64  `json:"size"`
}

func (h *blobHandler) path(key string) string {
	return filepath.Join(h.dataDir, filepath.FromSlash(key))
}

func (h *blobHandler) put(w http.ResponseWriter, r *http.Request) {
	key := r.PathValue("key")
	path := h.path(key)

	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		http.Error(w, "failed to create directory", http.StatusInternalServerError)
		return
	}

	data, err := io.ReadAll(r.Body)
	if err != nil {
		http.Error(w, "failed to read request body", http.StatusInternalServerError)
		return
	}

	if err := os.WriteFile(path, data, 0o644); err != nil {
		http.Error(w, "failed to write blob", http.StatusInternalServerError)
		return
	}

	sum := sha256.Sum256(data)
	resp := putResponse{
		Key:    key,
		SHA256: hex.EncodeToString(sum[:]),
		Size:   int64(len(data)),
	}

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(resp)
}

func (h *blobHandler) get(w http.ResponseWriter, r *http.Request) {
	key := r.PathValue("key")
	path := h.path(key)

	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			http.Error(w, "blob not found", http.StatusNotFound)
			return
		}
		http.Error(w, "failed to read blob", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/octet-stream")
	w.WriteHeader(http.StatusOK)
	w.Write(data)
}

