	dataDir := t.TempDir()
	handler := NewHandler(Config{DataDir: dataDir, Port: 8080})

	content := []byte("nested content")
	req := httptest.NewRequest(http.MethodPut, "/blobs/docs/readme.txt", bytes.NewReader(content))
